import java.time.LocalDateTime;

/** Happy-path tests, also generated by the agent. Plain main so no framework is needed. */
public class TradeReportServiceTest {

    static void check(boolean cond, String msg) {
        if (!cond) throw new AssertionError(msg);
        System.out.println("PASS " + msg);
    }

    public static void main(String[] args) {
        var svc = new TradeReportService(r -> true);
        var friday = LocalDateTime.of(2026, 10, 30, 14, 0);
        var t = new TradeReportService.Trade("T1", friday, 101.456, 1000,
                "XLON", "5493001KJTIIGC8Y1R12");

        var r = svc.create(t);
        check(r.dueDate().toString().equals("2026-11-02"), "Friday trade is due Monday");
        check(r.price() == 101.46, "price rounded to 2dp");
        check(r.counterpartyLei().equals("5493001KJTIIGC8Y1R12"), "valid LEI kept");

        var amended = svc.amend(new TradeReportService.Trade("T1", friday, 102.0, 1000,
                "XLON", "5493001KJTIIGC8Y1R12"));
        check(amended.type().equals("AMEND"), "amendment has AMEND type");

        svc.submitAll();
        check(true, "submitAll completes");
    }
}
